    function sectionSettings(existing){const type=byId('vegetation-type').value,asset=registry[type];return{id:existing?.id||`vegetation-${Date.now()}`,name:byId('vegetation-name').value.trim()||`${asset.label} ${state.vegetationSections.length+1}`,polygon:existing?.polygon||points.map(p=>p.slice()),vegetationType:type,foliageColor:byId('vegetation-color').value||asset.defaultColor,density:clamp(number('vegetation-density',30),1,120),minimumSpacing:clamp(number('vegetation-spacing',4),1,30),scaleRange:[Math.max(.2,1-number('vegetation-variation',30)/100),1+number('vegetation-variation',30)/100],heightRange:[Math.max(.2,number('vegetation-height-min',asset.heightRange[0])),Math.max(.3,number('vegetation-height-max',asset.heightRange[1]))],rotationRange:[0,360],modelVariants:asset.models.slice(),randomSeed:existing?.randomSeed||seedValue()}}
    function select(kind,id){selected={kind,id};const object=kind==='object'?state.objects3d.find(x=>x.id===id):null,section=kind==='section'?state.vegetationSections.find(x=>x.id===id):null;byId('object-selection').hidden=false;byId('selected-object-fields').hidden=!object;byId('selected-section-fields').hidden=!section;if(object){const asset=registry[object.assetType]||registry.deciduous;byId('selected-title').textContent=asset.label;byId('selected-rotation').value=object.rotation;byId('selected-scale').value=object.scale;byId('selected-height').value=object.height;byId('selected-foliage-color').value=object.foliageColor||asset.defaultColor}if(section){const asset=registry[section.vegetationType]||registry.deciduous;byId('selected-title').textContent=section.name;byId('vegetation-type').value=section.vegetationType;byId('vegetation-name').value=section.name;byId('vegetation-color').value=section.foliageColor||asset.defaultColor;byId('vegetation-density').value=section.density;byId('vegetation-spacing').value=section.minimumSpacing;byId('vegetation-variation').value=Math.round((section.scaleRange[1]-1)*100);byId('vegetation-height-min').value=section.heightRange[0];byId('vegetation-height-max').value=section.heightRange[1];updateRangeValues()}render()}
